"· piano del boss":"· boss floor",
"Il cancello del Borgo delle Ceneri è sbarrato da catene arrugginite. Il Moreau, qui accanto, sa come aprirlo.":"The gate of Ashenburg is barred with rusty chains. Moreau, right next door, knows how to open it.",
"Guardia del Castello":"Castle Guard",
"Recluta di ronda":"Patrol Recruit",
"Tabellone dell'Arena":"Arena Board",
