"La Vedova Nera · Arrembaggio":"The Black Widow · Boarding",
"L'Ammiraglio non ti fa salire a bordo: torna al livello 4.":"The Admiral won't let you aboard: come back at level 4.",
"Battaglia navale":"Naval battle",
"Tieni la rotta nella tempesta e rispondi al fuoco della Vedova Nera!":"Hold your course through the storm and return the Black Widow's fire!",
"Manovra!":"Maneuver!",
"Schivata!":"Dodged!",
"Barile di rum! +15 scafo":"Rum barrel! +15 hull",
"Alberi spezzati! La Vedova Nera non può sparare per un po'":"Masts broken! The Black Widow can't fire for a while",
"Colpo perfetto!":"Perfect shot!",
"All'arrembaggio!":"Board her!",
"La Vedova Nera affonda: salta a bordo e affronta la ciurma!":"The Black Widow is sinking: jump aboard and face the crew!",
"La tua nave è affondata":"Your ship has sunk",
"I pescatori ti riportano al porto":"The fishermen bring you back to the harbor",
"Salta il prologo ▸":"Skip prologue ▸",
"Portiera Rosalba":"Rosalba the Concierge",
"Benvenuto al Motel della Rosa dei Venti! Stanze pulite e bauli robusti.":"Welcome to the Compass Rose Motel! Clean rooms and sturdy chests.",
"Le stanze sono al primo piano: le scale sono lì, a destra.":"The rooms are on the first floor: the stairs are there, on the right.",
"Viaggiatore stanco":"Weary Traveler",
"Tre giorni di cammino da Khem. Finalmente un letto.":"Three days' walk from Khem. A bed at last.",
"Il baule della mia stanza è più sicuro di una banca, dicono.":"The chest in my room is safer than a bank, they say.",
"Ammiraglio Corvo":"Admiral Corvo",
"La Sfida ha venti cannoni e un equipaggio che non ha paura di niente.":"The Challenge has twenty cannons and a crew that fears nothing.",
"I pirati della Vedova Nera assaltano le nostre navi. È ora di dar loro una lezione.":"The Black Widow's pirates attack our ships. It's time to teach them a lesson.",
"Il terrore dei mari":"Terror of the Seas",
"Il Capitano Scarlatto comanda la Vedova Nera. Salpa con la Sfida, affondala a cannonate, abbordala e sconfiggilo.":"Captain Scarlet commands the Black Widow. Set sail on the Challenge, pound her with cannon fire, board her and defeat him.",
"Ciurma di tagliagole":"Crew of Cutthroats",
"Ogni pirata in meno è una nave mercantile salva. Abbattine 15 durante gli arrembaggi.":"Every pirate less is a merchant ship saved. Take down 15 during the boardings.",
