"Ti riposi accanto al fuoco: la vita torna piano piano.":"You rest by the fire: your health slowly returns.",
"Scale (sinistra) · primo piano":"Stairs (left) · first floor",
"Scale (destra) · primo piano":"Stairs (right) · first floor",
