"Bacchetta":"Wand",
"Verga":"Rod",
"Fornaia Gemma":"Gemma the Baker",
"Il primo pane esce dal forno alle cinque. Chi dorme non lo assaggia!":"The first bread comes out of the oven at five. Sleepyheads don't get a taste!",
"La farina dei Campi è la migliore del regno.":"Flour from the Fields is the best in the kingdom.",
"Sarta Ottavia":"Ottavia the Tailor",
"Ago, filo e pazienza: con questi vesto mezza Aldoria.":"Needle, thread and patience: with these I dress half of Aldoria.",
"La seta dei ragni di cristallo non si strappa mai.":"Crystal spider silk never tears.",
"Cliente":"Customer",
"Ottavia è la migliore, ma quanta fila!":"Ottavia is the best, but what a queue!",
"Capitano Ruggero":"Captain Ruggero",
"La Guardia di Aldoria non dorme mai. Al massimo sonnecchia.":"The Aldoria Guard never sleeps. At most it dozes.",
"Le reclute di quest'anno? Volenterose. E goffe.":"This year's recruits? Willing. And clumsy.",
"Recluta Pino":"Pino the Recruit",
"Sono di ronda! ...Credo di essermi perso.":"I'm on patrol! ...I think I'm lost.",
"Un giorno sarò capitano anch'io.":"One day I'll be a captain too.",
"Hai visto il Capitano? Non dirgli che ho fatto una pausa.":"Have you seen the Captain? Don't tell him I took a break.",
"Scudiero Aldo":"Aldo the Squire",
"Ogni cavallo ha il suo carattere. Tempesta, per esempio, morde.":"Every horse has its own temper. Storm, for example, bites.",
"Il fieno va cambiato ogni mattina.":"The hay must be changed every morning.",
"Saetta":"Bolt",
"Hiiiih!":"Neeeigh!",
"Il cavallo sbuffa e ti annusa le tasche.":"The horse snorts and sniffs your pockets.",
"Biscotto":"Biscuit",
"Il cavallo bianco ti guarda con aria nobile.":"The white horse looks at you with a noble air.",
"Hiiih!":"Neigh!",
"Tempesta":"Storm",
"Il cavallo nero batte lo zoccolo. Meglio non avvicinarsi troppo.":"The black horse stamps its hoof. Better not get too close.",
"Sbuff!":"Snort!",
"Astronomo Tolomeo":"Tolomeo the Astronomer",
"Di giorno dormo, di notte guardo il cielo. Che vita!":"By day I sleep, by night I watch the sky. What a life!",
"Stanotte Vespero brilla sopra il Colosseo.":"Tonight Vesper shines above the Colosseum.",
"Sindaco Bernardo":"Mayor Bernardo",
"Aldoria cresce: nuove strade, nuove case, nuovi problemi.":"Aldoria is growing: new streets, new houses, new problems.",
"Il Re regna, ma i tombini li sistemo io.":"The King reigns, but I'm the one who fixes the drains.",
"Usciere Fulvio":"Fulvio the Usher",
"Il Sindaco riceve dal lunedì al venerdì. Oggi che giorno è?":"The Mayor receives Monday to Friday. What day is it today?",
"Prenda il numero, prego.":"Take a number, please.",
"Segretaria Livia":"Livia the Secretary",
"Tre copie di ogni documento. Sempre.":"Three copies of every document. Always.",
"Il Sindaco firma tutto, ma legge poco.":"The Mayor signs everything, but reads little.",
"Garzone Lillo":"Lillo the Errand Boy",
"Ho le braccia di farina fino ai gomiti.":"I'm covered in flour up to my elbows.",
"Vuoi un panino? Due monete. Per gli eroi, tre.":"Want a roll? Two coins. For heroes, three.",
"Il forno non si ferma mai: portami 15 covoni di grano dai Campi.":"The oven never stops: bring me 15 sheaves of wheat from the Fields.",
"Seta di ragno":"Spider silk",
"Seta di cristallo":"Crystal Silk",
"I ragni delle Caverne di Cristallo filano la seta più resistente. Portamene 5 matasse.":"The spiders of the Crystal Caverns spin the toughest silk. Bring me 5 skeins.",
"Addestramento sul campo":"Field Training",
"Le mie reclute non hanno mai visto un goblin. Mostra loro come si fa: 15 goblin.":"My recruits have never seen a goblin. Show them how it's done: 15 goblins.",
"Mele per i cavalli":"Apples for the Horses",
"Saetta, Biscotto e Tempesta impazziscono per le mele dei Campi. Portamene 10.":"Bolt, Biscuit and Storm go crazy for apples from the Fields. Bring me 10.",
"Luci sul mare":"Lights on the Sea",
"Il guardiano del faro, al Porto, vede il cielo meglio di chiunque. Chiedigli delle luci che si muovono sull'acqua.":"The lighthouse keeper, at the Harbor, sees the sky better than anyone. Ask him about the lights moving on the water.",
"Stormi di pipistrelli salgono dalla Cripta e mi coprono le stelle. Sfoltiscili: 10 pipistrelli.":"Swarms of bats rise from the Crypt and hide my stars. Thin them out: 10 bats.",
"La festa del patrono":"The Patron Saint's Feast",
"Per la festa del patrono serve il pane per tutta la città. Avvisa la fornaia Gemma, alla Panetteria.":"For the patron saint's feast we need bread for the whole city. Tell Gemma the baker, at the Bakery.",
"Il falò della festa":"The Feast Bonfire",
"Il grande falò in piazza vuole 20 fasci di legna. I boscaioli dei Campi ne hanno in abbondanza.":"The great bonfire in the square needs 20 bundles of wood. The woodcutters of the Fields have plenty.",
