"Malakar... è caduto? Raccontami tutto, Campione.":"Malakar... has fallen? Tell me everything, Champion.",
"Aldoria ti sarà per sempre grata, Campione. Non mi sono mai sentito così forte: sento il regno intero tra le mani.":"Aldoria will be forever grateful to you, Champion. I've never felt so strong: I can feel the whole kingdom in my hands.",
