"Ultra è la grafica più ricca e richiede un computer più potente: se il gioco rallenta, torna ad Alta.":"Ultra is the richest graphics setting and needs a more powerful computer: if the game slows down, go back to High.",
"Fotogrammi":"Frames",
"Come lo schermo (consigliato)":"Match the screen (recommended)",
"Il tuo schermo aggiorna a circa {0} Hz.":"Your screen refreshes at about {0} Hz.",
"FPS massimi":"Max FPS",
"Il gioco è sempre sincronizzato con lo schermo: un browser non può mostrare più fotogrammi di quanti lo schermo ne aggiorni, quindi un limite più alto della frequenza dello schermo non cambia niente. Un limite più basso (30 o 60) fa scaldare meno portatili e telefoni e consuma meno batteria.":"The game is always synchronized with the screen: a browser can't show more frames than the screen refreshes, so a limit above the screen's refresh rate changes nothing. A lower limit (30 or 60) keeps laptops and phones cooler and saves battery.",
"⚡ Rendering veloce (consigliato)":"⚡ Fast rendering (recommended)",
"Muri, case, alberi e arredi che non si muovono vengono disegnati una volta sola e poi copiati, invece di essere ridisegnati pezzo per pezzo a ogni fotogramma: il gioco è molto più fluido, soprattutto con lo zoom lontano e nelle zone grandi. Disattivalo solo se noti qualcosa disegnato in modo strano.":"Walls, houses, trees and furniture that don't move are drawn once and then copied, instead of being redrawn piece by piece every frame: the game runs much more smoothly, especially when zoomed out and in large areas. Turn it off only if something looks oddly drawn.",
"Misura":"Measure",
"Contatore FPS":"FPS counter",
"Se il gioco va a scatti, abbassa anche la risoluzione o la preimpostazione nella sezione Grafica.":"If the game stutters, also lower the resolution or the preset in the Graphics section.",
