"{0} Personalizza l'HUD":"{0} Customize the HUD",
"Trascina gli elementi per spostarli · − e + (o la rotellina) per la grandezza · ↺ o doppio clic per rimetterlo al suo posto":"Drag elements to move them · − and + (or the wheel) to resize · ↺ or double-click to put it back",
"Aggancio alle linee guida":"Snap to guide lines",
"Le linee guida compaiono mentre trascini: bordi e centro dello schermo e degli altri elementi. Tieni premuto Alt per spostare liberamente.":"Guide lines appear while you drag: edges and center of the screen and of the other elements. Hold Alt to move freely.",
"Fatto":"Done",
"↺ Al suo posto":"↺ Back in place",
"Tocca un elemento per sceglierlo, trascinalo per spostarlo.":"Tap an element to select it, drag it to move it.",
"Hai trovato tutti i {0} segreti · +1000 oro":"You found all {0} secrets · +1000 gold",
"In fondo al pozzo prosciugato della vecchia piazza, avvolto in un panno nero, c'è un frammento che nessuno ha mai visto. È più scuro degli altri sei, e caldo come qualcosa di vivo. È il settimo cuore della Corona: la serratura dell'Occhio.{0}":"At the bottom of the dried-up well in the old square, wrapped in a black cloth, lies a shard no one has ever seen. It's darker than the other six, and warm like something alive. It's the seventh heart of the Crown: the lock of the Eye.{0}",
"❓ Domande":"❓ Questions",
"{0} ━━━━━━━━━━ Hai riunito tutti i pezzi della verità. {1}":"{0} ━━━━━━━━━━ You have gathered every piece of the truth. {1}",
"Hai il settimo cuore della Corona. Portalo al Re{0}":"You have the seventh heart of the Crown. Take it to the King{0}",
"Il Re Aldric ti attende nel castello a nord-ovest: segui il ! giallo sopra la sua testa. {0}":"King Aldric awaits you in the castle to the north-west: follow the yellow ! above his head. {0}",
"Mille anni fa, Aldric il Primo fondò Aldoria sulle rive del mare, dove la pietra incontra la luce.":"A thousand years ago, Aldric the First founded Aldoria on the shores of the sea, where stone meets light.",
"Per tenere unito il regno forgiò la Corona di Voxel: sei gemme, sei terre, un solo cuore.":"To hold the kingdom together he forged the Voxel Crown: six gems, six lands, a single heart.",
"Ma sotto le strade della città qualcosa dormiva. Aldric il Primo lo chiuse nella pietra, e giurò che nessuno dei suoi eredi lo avrebbe mai svegliato.":"But beneath the city's streets something slept. Aldric the First sealed it in stone, and swore that none of his heirs would ever wake it.",
"Per secoli Aldoria prosperò. I mercati erano pieni, le campane suonavano, e i figli del re crescevano insieme.":"For centuries Aldoria prospered. The markets were full, the bells rang, and the king's children grew up together.",
"Ma Malakar, fratello del Re Aldric, bramava quel potere. Studiò le arti proibite, e divenne il Re Lich.":"But Malakar, brother of King Aldric, craved that power. He studied the forbidden arts, and became the Lich King.",
"Una notte la nebbia salì da sotto Aldoria Vecchia. Fuoco. Urla. Poi, il silenzio.":"One night the fog rose from beneath Old Aldoria. Fire. Screams. Then, silence.",
"In quella stessa notte Malakar infranse la Corona. Sei frammenti volarono lontano, nei luoghi più oscuri del regno.":"That same night Malakar shattered the Crown. Six shards flew far away, to the darkest places of the kingdom.",
"La Tana dei Goblin, la Cripta Dimenticata, la Piramide di Khem, le Caverne di Cristallo, la Fucina Infernale, l'Abisso Sommerso: ogni frammento è custodito da un signore terribile.":"The Goblin Den, the Forgotten Crypt, the Pyramid of Khem, the Crystal Caverns, the Infernal Forge, the Sunken Abyss: each shard is guarded by a terrible lord.",
"English è la lingua di partenza del gioco (la traduzione si completa a tappe); Italiano mostra il testo originale. L'eldoriano è la lingua antica del regno: trasforma tutti i testi, sempre allo stesso modo.":"English is the game's default language (the translation is being completed in stages); Italiano shows the original Italian text. Eldorian is the kingdom's ancient tongue: it transforms every text, always in the same way.",
"Dalla sua Cittadella del Vuoto, Malakar attende che il regno cada nell'ombra. E i dungeon rinascono, più forti, a ogni ciclo.":"From his Void Citadel, Malakar waits for the kingdom to fall into shadow. And the dungeons are reborn, stronger, with every cycle.",
"Il Re fece murare il vecchio quartiere e proibì di parlarne. Ma ad Aldoria i segreti non dormono mai a lungo.":"The King had the old quarter walled up and forbade anyone to speak of it. But in Aldoria secrets never sleep for long.",
"Il Re Aldric cerca un eroe capace di riunire la Corona. Quell'eroe sei tu.":"King Aldric seeks a hero able to reunite the Crown. That hero is you.",
"Fruttivendola Nora":"Nora the Greengrocer",
"Mele, pere, arance! Tutto fresco di stamattina!":"Apples, pears, oranges! All fresh this morning!",
"Le prime fragole della stagione, assaggia!":"The first strawberries of the season, have a taste!",
"Mele rosse, mele dolci!":"Red apples, sweet apples!",
"Arance di Khem!":"Oranges from Khem!",
"Fragole fresche!":"Fresh strawberries!",
"Pescivendolo Tano":"Tano the Fishmonger",
"Pescato all'alba, giuro sulla mia barca!":"Caught at dawn, I swear on my boat!",
"Le sardine di oggi sono una meraviglia.":"Today's sardines are a marvel.",
"Pesce fresco!":"Fresh fish!",
"Sardine, spigole, orate!":"Sardines, sea bass, sea bream!",
"Pescato all'alba!":"Caught at dawn!",
"Fornaio Beppe":"Beppe the Baker",
"Il pane della Panetteria di Gemma, ancora caldo!":"Bread from Gemma's Bakery, still warm!",
"Le focacce finiscono prima di mezzogiorno.":"The focaccia sells out before noon.",
"Pane caldo!":"Warm bread!",
"Focacce al rosmarino!":"Rosemary focaccia!",
"Ciambelle!":"Donuts!",
"Fioraia Viola":"Viola the Florist",
"Un mazzo di rose per qualcuno di speciale?":"A bunch of roses for someone special?",
"I fiori del Roseto, colti stamattina.":"Flowers from the Rose Garden, picked this morning.",
"Rose del Roseto!":"Roses from the Rose Garden!",
"Fiori freschi!":"Fresh flowers!",
"Un fiore per la vostra dama!":"A flower for your lady!",
"Guardia di ronda":"Patrol Guard",
"Di notte la città è nostra. Nessun pericolo, cittadino.":"At night the city is ours. No danger, citizen.",
"Torna a casa, è tardi. O sei un avventuriero? Allora stai attento.":"Go home, it's late. Or are you an adventurer? Then be careful.",
"Il Re vuole le strade sicure. Facciamo il giro della piazza ogni ora.":"The King wants the streets safe. We patrol the square every hour.",
"Castello del Re Aldric: le missioni principali, e tante stanze da esplorare (galleria, armeria, prigioni, consiglio, archivio, cucine, appartamenti)":"King Aldric's Castle: the main quests, and many rooms to explore (gallery, armory, dungeons, council, archive, kitchens, apartments)",
"Al centro: la grande fontana di Aldric il Primo e il mercato della piazza (aperto dalle 7 alle 19)":"In the center: the great fountain of Aldric the First and the square's market (open 7 to 19)",
"Di giorno le strade sono piene di gente; la sera i cittadini tornano a casa e restano solo le guardie, con le torce.":"By day the streets are crowded; in the evening the citizens go home and only the guards remain, with their torches.",
