"Canna di quercia":"Oak rod",
"Canna del Cavallo Pazzo":"Mad Horse's rod",
"Tieni premuto per caricare il lancio, poi rilascia.":"Hold to charge the cast, then release.",
"Lancio perfetto! L'amo vola lontano.":"Perfect cast! The hook flies far.",
"Lancio!":"Cast!",
"Era solo un assaggio! Il pesce è scappato: aspetta che abbocchi davvero.":"It was only a nibble! The fish got away: wait until it really bites.",
"Troppo presto! Hai spaventato il pesce.":"Too early! You scared the fish.",
"È ENORME! Tieni il pesce dentro la zona dorata!":"IT'S HUGE! Keep the fish inside the golden zone!",
"Ha abboccato! Tieni il pesce dentro la zona dorata.":"It bit! Keep the fish inside the golden zone.",
"Hai smesso di pescare.":"You stopped fishing.",
"Il galleggiante dondola... guarda le ombre sotto l'acqua.":"The float bobs... watch the shadows under the water.",
"ABBOCCA! Ferra subito!":"IT'S BITING! Strike now!",
"Troppo lento a ferrare: il pesce ha mangiato l'esca ed è scappato.":"Too slow to strike: the fish ate the bait and got away.",
"Va a fondo! La zona si stringe: tieni duro!":"It's diving! The zone is shrinking: hold on!",
"Tieni il pesce dentro la zona dorata!":"Keep the fish inside the golden zone!",
"Il pesce si è liberato ed è scappato.":"The fish broke free and got away.",
"LEGGENDARIO!":"LEGENDARY!",
