"🎣 Lancia (tieni premuto)":"🎣 Cast (hold)",
"⚡ Ferra":"⚡ Strike",
"⚡ FERRA!":"⚡ STRIKE!",
"🔄 Recupera (tieni premuto)":"🔄 Reel in (hold)",
"🎣 Lancia di nuovo":"🎣 Cast again",
"In mare aperto abboccano pesci più grossi.":"Out at sea bigger fish bite.",
"È notte: calamari e trote dorate salgono in superficie.":"It's night: squid and golden trout rise to the surface.",
"Di notte abboccano anche calamari e trote dorate.":"At night squid and golden trout bite too.",
