"Torre di Aldoria":"Aldoria tower",
"Ryan: «Scegli la corsia, poi manda le truppe! Distruggi il loro accampamento!»":"Ryan: “Pick the lane, then send in the troops! Destroy their camp!”",
"Ryan: «Il campo è pieno, soldato! Aspetta che si liberi.»":"Ryan: “The field is full, soldier! Wait for it to clear.”",
"Generale Varg":"General Varg",
"Il Generale Varg scende in campo!":"General Varg takes the field!",
"Fermalo prima che raggiunga il tuo accampamento":"Stop him before he reaches your camp",
"Il tuo accampamento è caduto.":"Your camp has fallen.",
"L'accampamento nemico crolla!":"The enemy camp collapses!",
"Torre nemica distrutta!":"Enemy tower destroyed!",
"Il tuo accampamento è caduto!":"Your camp has fallen!",
"Hanno distrutto una tua torre!":"They destroyed one of your towers!",
"Il Generale Varg è caduto!":"General Varg has fallen!",
"La Legione vacilla":"The Legion wavers",
"Ritirata!":"Retreat!",
"Ryan: «Che spettacolo, soldato! Vieni a prendere la tua ricompensa!»":"Ryan: “What a show, soldier! Come and collect your reward!”",
"Rifornimenti insufficienti":"Not enough supplies",
"Ryan: «Avanti, avanti, AVANTI!»":"Ryan: “Forward, forward, FORWARD!”",
"Ryan: «Tenete la posizione!»":"Ryan: “Hold your position!”",
"Ryan: «Ritirata! Tutti all'accampamento!»":"Ryan: “Retreat! Everyone back to camp!”",
"Le tue truppe si lanciano in avanti":"Your troops surge forward",
"Rinforzi!":"Reinforcements!",
"Una squadra di fanti arriva al campo":"An infantry squad arrives on the field",
"🏆 Vittoria!":"🏆 Victory!",
"💀 Sconfitta":"💀 Defeat",
"Il nemico è in rotta. Ryan esulta!":"The enemy is routed. Ryan cheers!",
"I tuoi soldati si ritirano. Riprova con un'altra strategia.":"Your soldiers retreat. Try again with another strategy.",
"Riprova la battaglia":"Retry the battle",
"Torna in caserma da Ryan":"Back to the barracks with Ryan",
"Centro":"Center",
"⚔ Avanza":"⚔ Advance",
"🛡 Difendi":"🛡 Defend",
"↩ Ritirata":"↩ Retreat",
"📯 CARICA! {0}s":"📯 CHARGE! {0}s",
"Hai suonato la ritirata.":"You sounded the retreat.",
"⚔ Sul campo di battaglia":"⚔ To the battlefield",
"· missione attiva":"· quest active",
"· prima vinci la battaglia precedente":"· first win the previous battle",
"Elmo del Pelato":"Bald Man's Helmet",
"Ryan ti regala il suo elmo. «Tanto a me non serve: lo porto lucido!»":"Ryan gives you his helmet. “I don't need it anyway: I wear mine shiny!”",
"Sei stato ferito: i tuoi soldati ti portano al sicuro.":"You were wounded: your soldiers carry you to safety.",
"Che vuoi?":"What do you want?",
"Ancora tu? Non ti basta il resto della taverna?":"You again? Isn't the rest of the tavern enough for you?",
"Se sei venuto a chiacchierare, la porta è là.":"If you came to chat, the door's over there.",
"Mmh. Parla, ma sbrigati.":"Hmm. Talk, but make it quick.",
"Non ho tempo. Ho una birra da finire e un muso da tenere.":"I don't have time. I've got a beer to finish and a sulk to keep up.",
"Hai la faccia di uno che fa domande. Odio quelli che fanno domande.":"You've got the face of someone who asks questions. I hate people who ask questions.",
"Buongiorno, Manuel!":"Good morning, Manuel!",
"Buongiorno un corno.":"Good morning my foot.",
"Era buono finché non sei arrivato tu.":"It was good until you showed up.",
"Il giorno è buono solo quando finisce.":"A day is only good when it's over.",
"Come stai?":"How are you?",
"Male. Come ieri. Come domani.":"Bad. Like yesterday. Like tomorrow.",
"Stavo meglio cinque minuti fa, prima della tua domanda.":"I was better five minutes ago, before your question.",
"Ho mal di schiena, mal di testa e mal di te.":"I've got a backache, a headache and a you-ache.",
"Che lavoro fai?":"What do you do for a living?",
"Il bevitore. A tempo pieno. Con gli straordinari.":"Drinker. Full time. With overtime.",
"Facevo il carpentiere. Poi ho capito che la gente è più storta del legno.":"I was a carpenter. Then I realized people are more crooked than wood.",
"Lavoravo. Poi mi sono stancato. Fine della storia.":"I used to work. Then I got tired. End of story.",
"Perché sei sempre arrabbiato?":"Why are you always angry?",
"Non sono arrabbiato! SONO ESATTAMENTE COME DEVO ESSERE!":"I'm not angry! I'M EXACTLY THE WAY I'M SUPPOSED TO BE!",
"Perché la gente fa domande come questa.":"Because people ask questions like that.",
"Vuoi davvero saperlo? No. Infatti non te lo dico.":"Do you really want to know? No. So I'm not telling you.",
"Hai qualche consiglio per me?":"Any advice for me?",
"Sì: lasciami in pace.":"Yes: leave me alone.",
"Non fidarti di nessuno. Specialmente di quelli che fanno domande.":"Don't trust anyone. Especially people who ask questions.",
"Bevi meno latte. E parla meno con me.":"Drink less milk. And talk to me less.",
"Conosci qualche segreto di Aldoria?":"Do you know any of Aldoria's secrets?",
"L'unico segreto è come faccio a sopportarvi tutti.":"The only secret is how I put up with all of you.",
"Sì. E me lo tengo.":"Yes. And I'm keeping it.",
"Il segreto è stare zitti. Provaci.":"The secret is keeping quiet. Try it.",
"Bella giornata, eh?":"Nice day, huh?",
"Per te, forse.":"For you, maybe.",
"Il sole mi dà fastidio. La pioggia pure. Anche tu.":"The sun bothers me. So does the rain. So do you.",
"Sì. Bellissima. Adesso rovinala andandotene.":"Yes. Lovely. Now ruin it by leaving.",
"Ti offro da bere! (5💰)":"Let me buy you a drink! (5💰)",
"BASTA! Mi fai venire il mal di testa!":"ENOUGH! You're giving me a headache!",
"Ancora?! Ti pago io per stare zitto!":"Again?! I'll pay YOU to shut up!",
"Ma tu non hai una casa? Un lavoro? Un drago da uccidere? VAI!":"Don't you have a home? A job? A dragon to slay? GO!",
"Non hai neanche cinque monete? E vuoi offrire da bere a me? Ah!":"You don't even have five coins? And you want to buy me a drink? Ha!",
"... Va bene. Una cosa te la dico. Al porto c'è uno matto come un cavallo, Stefano. Dicono che sappia dove nuotano i pesci d'oro. E in caserma c'è un pelato che cerca gente per le sue battaglie. Ecco. Non ti ho detto niente. E ora sparisci.":"... Fine. I'll tell you one thing. At the harbor there's a guy as mad as a horse, Stefano. They say he knows where the golden fish swim. And at the barracks there's a bald guy looking for people for his battles. There. I didn't tell you anything. Now get lost.",
"Lo bevo. Ma resto arrabbiato.":"I'll drink it. But I'm still angry.",
"Hmpf. Almeno qualcuno qui ha un po' di buon senso. Comunque vattene.":"Hmph. At least someone here has some sense. Now go away anyway.",
"Questa birra è calda. Come sempre. Come tutto, qui.":"This beer is warm. As always. Like everything here.",
"Era ora!":"About time!",
"Finalmente!":"Finally!",
"Non tornare!":"Don't come back!",
"Hmpf.":"Hmph.",
"Il mare di Stefano":"Stefano's Sea",
"Campi di battaglia":"Battlefields",
"Parla con Stefano «il Cavallo Pazzo» sul molo ovest del Porto: ti porta con la Puledra.":"Talk to Stefano “the Mad Horse” on the Harbor's west pier: he'll take you on the Filly.",
"Cinque mari, ognuno con i suoi pesci e una leggenda da pescare: la Scogliera dei Gabbiani, il Banco dei Tonni, la Fossa Profonda, la Grotta Marina e la Punta del Naufragio.":"Five seas, each with its own fish and a legend to catch: Seagull Cliffs, the Tuna Bank, the Deep Trench, the Sea Cave and Shipwreck Point.",
"Pesci del mare aperto, più grossi e rari":"Open-sea fish, bigger and rarer",
"Cinque pesci leggendari":"Five legendary fish",
"Il Diario del pescatore con i tuoi record":"The Angler's journal with your records",
"Parla con Gabriele «Ryan il Pelato» nella Caserma della Guardia.":"Talk to Gabriele “Ryan the Bald” in the Guard Barracks.",
"Cinque battaglie in cui comandi un esercito: scegli le truppe, la corsia e gli ordini, e distruggi l'accampamento nemico.":"Five battles where you command an army: choose the troops, the lane and the orders, and destroy the enemy camp.",
"Fanti, lancieri, arcieri, cavalieri e catapulte":"Infantry, spearmen, archers, knights and catapults",
"Torri da abbattere e un accampamento da difendere":"Towers to bring down and a camp to defend",
