"Il Re Aldric ti attende nel castello a nord-ovest: segui il ! giallo sopra la sua testa. I personaggi con ! hanno missioni da darti e ti pagano in monete. Le porte della città portano alla Foresta (nord), al Deserto (est) e ai Picchi Gelidi (ovest). Il Colosseo, con l'arena PvP e la classifica, è a nord-est. Dalle porte secondarie si va nei nuovi quartieri: il Quartiere Nobile (nord-ovest), i Campi (est), il Porto (sud) e il Borgo delle Ceneri (ovest, chiuso: chiedi al Moreau). I tasti utili: I zaino, J missioni, K diario, L classifica, P giocatori, O opzioni, WASD o frecce per muoverti, R per interagire, Q pozione, Spazio colpo ad area, Shift o E schivata, F affondo, Invio chat.":"King Aldric awaits you in the castle to the north-west: follow the yellow ! above his head. Characters with a ! have quests for you and pay you in coins. The city gates lead to the Forest (north), the Desert (east) and the Frozen Peaks (west). The Colosseum, with the PvP arena and the leaderboard, is to the north-east. The side gates lead to the new quarters: the Noble Quarter (north-west), the Fields (east), the Harbor (south) and Ashenburg (west, closed: ask Moreau). Useful keys: I backpack, J quests, K journal, L leaderboard, P players, O options, WASD or arrows to move, R to interact, Q potion, Space area strike, Shift or E dodge, F lunge, Enter chat.",
