"Lo Zaffiro si è spezzato, e la città del futuro se n'è andata con lui. I frammenti brillano ancora, piano. La Corona adesso guarda al Regno Perduto e a Tomorrow.":"The Sapphire has shattered, and the city of the future went with it. The fragments still glow, faintly. The Crown now looks to the Lost Kingdom and to Tomorrow.",
