"Schegge riunite: {0}/{1} · le vedi nell'Album della Corona":"Splinters gathered: {0}/{1} · see them in the Crown Album",
"Ondata {0}{1}/5 · {2}":"Wave {0}{1}/5 · {2}",
"{0} di Tomorrow":"{0} of Tomorrow",
"L'Eco della Corona si spezza in mille cubetti di luce, e ognuno torna nella sua epoca: i cavalieri nel regno, i banditi nel West, i guerrieri oltre il mare, le chimere nei mondi senza confini. Le schegge brillano insieme per la prima volta da mille anni, e perfino lo Zaffiro infranto manda un riflesso. La Corona non è più un'arma, né un ricordo: è un ponte. Tiene uniti i tempi, come un tempo teneva unite le terre. Torni ad Aldoria con la Corona Riunita sul capo. Nell'Album della Corona il finale vero di Voxelia è segnato per sempre.{0}":"The Echo of the Crown shatters into a thousand cubes of light, and each returns to its own era: the knights to the kingdom, the bandits to the West, the warriors beyond the sea, the chimeras to the borderless worlds. The splinters shine together for the first time in a thousand years, and even the Shattered Sapphire sends a gleam. The Crown is no longer a weapon, nor a memory: it is a bridge. It holds the ages together, as it once held the lands together. You return to Aldoria with the Reunited Crown on your head. In the Crown Album the true ending of Voxelia is recorded forever.{0}",
