"Serve un eroe della Storia: è lui che entra nel Cuore della Corona.":"You need a Story hero: they are the one who enters the Heart of the Crown.",
"Le cinque schegge si accendono tutte insieme e la Corona ti risucchia dentro. Sotto i tuoi piedi c'è un pavimento d'oro sospeso nel vuoto; intorno, cinque pilastri con le cinque schegge. Le epoche si stanno mescolando: dal passato, dalle terre d'Oltremare e dai mondi senza confini arriva tutto quello che la Corona ha visto. Resisti alle cinque ondate e affronta l'Eco della Corona.":"The five splinters light up all at once and the Crown draws you inside. Beneath your feet is a golden floor suspended in the void; around you, five pillars with the five splinters. The eras are blending: from the past, from the lands Overseas and from the borderless worlds comes everything the Crown has seen. Survive the five waves and face the Echo of the Crown.",
