"HP ×2,2, danni ×2. Morte permanente: se cadi, il salvataggio viene cancellato.":"HP ×2.2, damage ×2. Permadeath: if you fall, your save is deleted.",
"Prologo":"Prologue",
"La storia della Corona di Voxel, raccontata dall'inizio":"The story of the Voxel Crown, told from the beginning",
"Scene della storia":"Story scenes",
"Rivedi i filmati che hai già sbloccato giocando":"Rewatch the cutscenes you've already unlocked by playing",
"Una notte, nella Foresta di Elmwood, una cabina blu è apparsa dal nulla. Chi entra viene trascinato attraverso il tempo...":"One night, in Elmwood Forest, a blue cabin appeared out of nowhere. Whoever enters is dragged through time...",
"Il nome scritto nella Modalità Storia vale anche qui. Il viaggio si salva a parte e non tocca la tua partita della storia.":"The name you entered in Story Mode applies here too. The journey is saved separately and doesn't affect your story game.",
"🎡 Parco giochi · Voxelia Studio":"🎡 Playground · Voxelia Studio",
"Crea il tuo mondo con tutto ciò che c'è in Voxelia: terreni, muri, case, arredi, personaggi, nemici e boss. Scrivi dialoghi a scelte, missioni, armi con effetti speciali, musiche e cinematiche. Poi giocalo, pubblicalo nei Mondi della community o regalalo a un amico con un file.":"Create your world with everything in Voxelia: terrain, walls, houses, furniture, characters, enemies and bosses. Write branching dialogue, quests, weapons with special effects, music and cutscenes. Then play it, publish it in the Community worlds or give it to a friend as a file.",
"I mondi si salvano in questo browser. Esportali in un file per non perderli. Il nome scritto nella Modalità Storia vale anche qui.":"Worlds are saved in this browser. Export them to a file so you don't lose them. The name you entered in Story Mode applies here too.",
