"Regina Elara":"Queen Elara",
"Aldoria è la mia casa. E le case si difendono.":"Aldoria is my home. And homes are defended.",
"Malakar: «Il ventre! Quando si chiude, allontanati dall'acido e aspetta.»":"Malakar: “The belly! When it closes, get away from the acid and wait.”",
"L'eco della Regina":"The Queen's echo",
"Dal ventre squarciato esce l'ombra della Regina Elara":"From the torn belly emerges the shadow of Queen Elara",
"Malakar: «Elara... È lei. L'Abominio l'ha presa quella notte. Liberala, eroe: non è più lei.»":"Malakar: “Elara... It's her. The Abomination took her that night. Free her, hero: she's no longer herself.”",
"La testa si abbassa: colpiscila, e non restare davanti allo sguardo":"The head lowers: strike it, and don't stand in front of its gaze",
"Malakar: «Lo sguardo gira! Corrigli dietro, non davanti!»":"Malakar: “The gaze is turning! Run behind it, not in front!”",
"Il cuore dell'Abominio":"The heart of the Abomination",
"La nebbia si stringe: distruggi il cuore prima che ti soffochi":"The fog closes in: destroy the heart before it smothers you",
"Malakar: «Ora! Il cuore! Ti proteggo io, finché posso!»":"Malakar: “Now! The heart! I'll protect you, as long as I can!”",
"La Regina Elara è libera":"Queen Elara is free",
"La sua benedizione: i tuoi colpi sono più forti fino alla fine":"Her blessing: your strikes are stronger until the end",
"Elara: «I bambini sono al sicuro... Di' a Malakar che gli ho sempre creduto.»":"Elara: “The children are safe... Tell Malakar I always believed him.”",
"Scudo di Malakar":"Malakar's Shield",
"Si chiude!":"It's closing!",
"Vomito!":"Spew!",
"Lamento!":"Wail!",
"Lo sguardo!":"The gaze!",
"L'Abominio impazzisce":"The Abomination goes berserk",
"Ogni colpo fa più male: finiscilo!":"Every hit hurts more: finish it!",
"Lo scudo di Malakar ti avvolge":"Malakar's shield surrounds you",
"Con questa chiave aprirai la porta di pietra nella stanza del culto. Dietro c'è l'Occhio. Prima le braccia, poi il ventre. Dentro troverai qualcuno che conoscevo: liberala. Poi la testa, e per ultimo il cuore, quando la nebbia si stringerà. Io sarò con te, per quanto può esserlo un fantasma.":"With this key you'll open the stone door in the cult's chamber. Behind it is the Eye. First the arms, then the belly. Inside you'll find someone I knew: free her. Then the head, and last of all the heart, when the fog closes in. I'll be with you, as much as a ghost can be.",
"«Il varco ti porta nella stanza del culto. Apri la porta di pietra. Le braccia, il ventre, chi è prigioniero dentro, la testa, il cuore. E leggi la terra: i cerchi rossi dicono dove colpirà.»":"“The rift takes you to the cult's chamber. Open the stone door. The arms, the belly, the one imprisoned inside, the head, the heart. And read the ground: the red circles tell you where it will strike.”",
