": l'eroe viene preparato per il combattimento e parte già davanti al boss. Non si salva niente e non si usa il server: classifica, punti arena, cicli dei dungeon e plugin non vedono nulla. Niente ricompense: alla fine vedi com'è andata.{0}":": the hero is prepared for combat and starts right in front of the boss. Nothing is saved and the server isn't used: leaderboard, arena points, dungeon cycles and plugins see nothing. No rewards: at the end you see how it went.{0}",
