"Arrivo":"Arrival",
"Una nuova leggenda comincia":"A new legend begins",
"Un nuovo viaggio nel tempo":"A new journey through time",
"Il viaggio riprende":"The journey resumes",
"Un mondo della community":"A community world",
"Si gioca il tuo mondo":"Playing your world",
"La saga di Aldoria":"The saga of Aldoria",
"L'ombra di Malakar":"The shadow of Malakar",
"L'alba dell'eroe":"The hero's dawn",
"Mille anni fa il mondo era giovane, e il mare non aveva nomi. Su una nave sola, Aldric il Primo arrivò a una costa di pietra bianca.":"A thousand years ago the world was young, and the sea had no names. On a lone ship, Aldric the First came to a coast of white stone.",
"Lì, dove la pietra incontra la luce, fondò Aldoria: prima un muro, poi una torre, poi una città intera.":"There, where stone meets light, he founded Aldoria: first a wall, then a tower, then a whole city.",
"I boschi, le cripte, le sabbie di Khem, le caverne di cristallo, le fucine di fuoco e gli abissi del mare: finché la Corona restava intera, le sei terre vivevano in pace.":"The woods, the crypts, the sands of Khem, the crystal caves, the fiery forges and the depths of the sea: as long as the Crown stayed whole, the six lands lived in peace.",
"Ma Malakar, il fratello del re, passava le notti sui libri proibiti del Primo Re. Cercava un potere più grande della Corona.":"But Malakar, the king's brother, spent his nights over the First King's forbidden books. He sought a power greater than the Crown.",
"Così racconta il Re: Malakar bramava il potere della Corona, e le arti proibite lo trasformarono nel Re Lich.":"So the King tells it: Malakar craved the Crown's power, and the forbidden arts turned him into the Lich King.",
"In quella stessa notte la Corona andò in pezzi. Sei frammenti attraversarono il cielo e caddero lontano, nei luoghi più oscuri del regno.":"That same night the Crown shattered. Six shards crossed the sky and fell far away, in the darkest places of the kingdom.",
"Oggi il Re Aldric cerca un eroe capace di riunire la Corona. Quell'eroe sei tu.":"Today King Aldric seeks a hero able to reunite the Crown. That hero is you.",
