"la Spada di Aldoria":"the Sword of Aldoria",
"Via dell'equilibrio":"Path of Balance",
"Né troppo buono né troppo duro: il regno non sa ancora che cosa aspettarsi da te.":"Neither too kind nor too harsh: the kingdom doesn't yet know what to expect from you.",
"il Custode dell'Equilibrio":"the Keeper of Balance",
