"Si arrende!":"Surrenders!",
"Non c'è nessuno da giudicare.":"There's no one to judge.",
"⚖ {0} si arrende":"⚖ {0} surrenders",
"«Basta… hai vinto. Fa' di me quello che vuoi.» La sua arma è a terra. Il bottino è lo stesso, ma quello che scegli resta nella storia{0}.":"“Enough… you've won. Do what you want with me.” Their weapon is on the ground. The loot is the same, but what you choose stays in history{0}.",
