"Giurerà di non fare più del male e diventerà un tuo alleato ad Aldoria.":"They'll swear to do no more harm and become your ally in Aldoria.",
"Finiscilo":"Finish them",
"Il regno sarà più sicuro, e la tua fama di guerriero crescerà.":"The kingdom will be safer, and your fame as a warrior will grow.",
"Via di adesso: {0} {1} ({2}{3})":"Current path: {0} {1} ({2}{3})",
"Lo ritroverai nella Casa degli alleati, ad Aldoria":"You'll find them again in the Allies' House, in Aldoria",
"Il regno è più sicuro, e la tua fama di guerriero cresce":"The kingdom is safer, and your fame as a warrior grows",
"Un ragazzino affamato ha rubato una mela al mercato e la fruttivendola lo tiene per un orecchio.":"A hungry boy stole an apple at the market and the greengrocer is holding him by the ear.",
"Paga tu la mela e lascialo andare":"Pay for the apple yourself and let him go",
"Consegnalo alle guardie":"Hand him over to the guards",
"Una vedova ti chiede aiuto per riparare il tetto prima della pioggia.":"A widow asks you for help fixing her roof before the rain.",
"Aiutala senza chiedere niente":"Help her without asking for anything",
"Aiutala, ma fatti pagare":"Help her, but get paid",
"Fuori dalle mura un goblin ferito chiede pietà: dice che il suo clan lo ha cacciato.":"Outside the walls a wounded goblin begs for mercy: he says his clan threw him out.",
"Curalo e lascialo andare":"Heal him and let him go",
"Un mercante ti offre a metà prezzo una spada che, sei quasi sicuro, è stata rubata.":"A merchant offers you a sword at half price that you're almost sure was stolen.",
"Rifiuta e avvisa il proprietario":"Refuse and warn the owner",
"Comprala per 120 monete":"Buy it for 120 coins",
"Un bambino ha perso il suo cane vicino al porto e piange sulla banchina.":"A child lost his dog near the harbor and is crying on the quay.",
"Cercalo insieme a lui":"Look for it with him",
"Non hai tempo: tira dritto":"You don't have time: keep walking",
"Due contadini litigano per l'acqua del pozzo e tutti e due ti chiedono di decidere.":"Two farmers are arguing over the well water and both ask you to decide.",
"Dividi l'acqua in parti uguali":"Split the water equally",
"Dai ragione a chi ti paga":"Side with whoever pays you",
"Un vecchio soldato ubriaco ha rotto una finestra della taverna e non ha i soldi per ripagarla.":"A drunk old soldier broke a tavern window and has no money to pay for it.",
