"La casa è vuota: quando un boss si arrende, risparmialo.":"The house is empty: when a boss surrenders, spare them.",
"🕊 Casa degli alleati":"🕊 Allies' House",
"Qui vivono i nemici che hai risparmiato. Ogni giorno ognuno ti fa un dono{0}.":"The enemies you spared live here. Every day each of them gives you a gift{0}.",
"Il Viandante":"The Wanderer",
"Casa degli alleati":"Allies' House",
"Anni dopo, nelle taverne di Aldoria si racconta di un eroe che vinse ogni battaglia e non uccise mai chi si arrendeva. I nemici di un tempo vivono in città, e i bambini non hanno più paura dei goblin. Il regno ti chiama «il Misericordioso».":"Years later, Aldoria's taverns tell of a hero who won every battle and never killed those who surrendered. Former enemies live in the city, and children are no longer afraid of goblins. The kingdom calls you “the Merciful”.",
"Anni dopo, i nomi dei mostri che hai abbattuto sono incisi sulle mura della città, e nessun nemico osa più avvicinarsi ai confini. Il regno è sicuro, e un po' ti teme. Ti chiamano «la Spada di Aldoria».":"Years later, the names of the monsters you slew are carved on the city walls, and no enemy dares approach the borders anymore. The kingdom is safe, and a little afraid of you. They call you “the Sword of Aldoria”.",
"Anni dopo, nessuno sa dire se tu fossi più buono o più duro: sapevi quando tendere la mano e quando sguainare la spada. Il regno ti chiama «il Custode dell'Equilibrio».":"Years later, no one can say whether you were kinder or harsher: you knew when to offer a hand and when to draw the sword. The kingdom calls you “the Keeper of Balance”.",
"tuoi vecchi nemici sono venuti":"of your old enemies came",
"tuo vecchio nemico è venuto":"of your old enemies came",
"📜 Cronaca delle tue scelte":"📜 Chronicle of your choices",
"I boss":"The bosses",
